import { Router } from 'express';
import bcrypt from 'bcryptjs';
import { z } from 'zod';
import { db } from './lib.js';
import { admin, asyncHandler, auth } from './middleware.js';
export const databaseAdmin = Router();
const backupSchema = z.object({ format: z.literal('seguridad-rrhh-backup'), version: z.literal(1), data: z.object({ recintos: z.array(z.record(z.any())), guardias: z.array(z.record(z.any())), turnos: z.array(z.record(z.any())), rondas: z.array(z.record(z.any())), entradas: z.array(z.record(z.any())), reportes: z.array(z.record(z.any())), alertas: z.array(z.record(z.any())), relevos: z.array(z.record(z.any())).optional().default([]), configuracion: z.record(z.any()).nullable().optional() }) });
const rrhhBackupSchema = z.object({ format: z.literal('seguridad-rrhh-backup'), version: z.literal(1), data: z.object({ trabajadores: z.array(z.record(z.any())), eventos: z.array(z.record(z.any())), amonestaciones: z.array(z.record(z.any())) }) });
const recintoRowsSchema = z.array(z.object({ nombre: z.string().trim().min(1), direccion: z.string().trim().min(1), tipo: z.string().trim().min(1), estado: z.enum(['Activo', 'Inactivo']).default('Activo') }).passthrough());
const recintosBackupSchema = z.union([z.object({ format: z.literal('seguridad-rrhh-recintos-backup'), version: z.literal(1), data: z.object({ recintos: recintoRowsSchema }) }), recintoRowsSchema]);
const configurationFields = ['permitir_registro_publico', 'login_max_attempts', 'login_lock_minutes', 'login_ban_email_enabled', 'login_ban_telegram_enabled', 'nextcloud_enabled', 'nextcloud_url', 'nextcloud_user', 'nextcloud_folder', 'smtp_host', 'smtp_port', 'smtp_secure', 'smtp_user', 'mail_from', 'telegram_enabled', 'telegram_chat_id', 'shift_email_enabled', 'timezone', 'date_format', 'time_format', 'turno_dia_inicio', 'turno_dia_fin', 'turno_manana_inicio', 'turno_manana_fin', 'turno_tarde_inicio', 'turno_tarde_fin', 'turno_noche_inicio', 'turno_noche_fin', 'turno_dia_color', 'turno_noche_color', 'turno_personalizado_color', 'theme', 'brand_name', 'brand_subtitle', 'hero_title', 'hero_description', 'hero_footer', 'logo_url', 'icon_url', 'hero_image_url', 'public_page_enabled', 'public_banner_color', 'company_contact_enabled', 'company_contact_name', 'company_email', 'company_phone', 'company_address', 'company_website_url', 'company_title', 'company_description', 'company_services', 'quote_email'];
const dateFields = { recintos: ['created_at', 'updated_at'], guardias: ['fecha_ingreso', 'created_at', 'updated_at'], turnos: ['fecha', 'created_at', 'updated_at'], rondas: ['fecha_hora_inicio', 'fecha_hora_fin', 'created_at', 'updated_at'], entradas: ['hora_entrada', 'hora_salida', 'created_at', 'updated_at'], reportes: ['fecha', 'created_at', 'updated_at'], alertas: ['fecha', 'created_at', 'updated_at'], relevos: ['fecha_hora', 'created_at', 'updated_at'], trabajadores: ['fecha_nacimiento', 'fecha_ingreso', 'fecha_termino', 'created_at', 'updated_at'], eventos: ['fecha_inicio', 'fecha_fin', 'created_at', 'updated_at'], amonestaciones: ['fecha_hecho', 'fecha_notificacion', 'enviada_email_at', 'created_at', 'updated_at'] };
const moduleScopes = { guardias: { model: 'guardia', rows: 'guardias', label: 'Guardias' }, turnos: { model: 'turno', rows: 'turnos', label: 'Turnos' }, rondas: { model: 'ronda', rows: 'rondas', label: 'Rondas' }, entradas: { model: 'entrada', rows: 'entradas', label: 'Entradas' }, reportes: { model: 'reporte', rows: 'reportes', label: 'Reportes' }, alertas: { model: 'alerta', rows: 'alertas', label: 'Alertas' }, relevos: { model: 'relevo', rows: 'relevos', label: 'Relevos' } };
const moduleBackupSchema = z.object({ format: z.string(), version: z.literal(1), data: z.record(z.array(z.record(z.any()))) });
function rowsForImport(name, rows, userIds) { return rows.map(row => { const value = { ...row }; for (const field of dateFields[name] || [])
    if (value[field])
        value[field] = new Date(value[field]); if ('created_by_id' in value && !userIds.has(value.created_by_id))
    value.created_by_id = null; return value; }); }
async function clearOperationalData(tx) { await tx.relevo.deleteMany(); await tx.alerta.deleteMany(); await tx.reporte.deleteMany(); await tx.entrada.deleteMany(); await tx.ronda.deleteMany(); await tx.turno.deleteMany(); await tx.guardia.deleteMany(); await tx.recinto.deleteMany(); }
async function verifyPassword(userId, password) { const user = await db.user.findUnique({ where: { id: userId } }); return !!user?.password && bcrypt.compare(password, user.password); }
async function clearRrhhData(tx) { await tx.amonestacion.deleteMany(); await tx.eventoRRHH.deleteMany(); await tx.trabajador.deleteMany(); }
databaseAdmin.get('/export', auth, admin, asyncHandler(async (_req, res) => { const [recintos, guardias, turnos, rondas, entradas, reportes, alertas, relevos, config] = await Promise.all([db.recinto.findMany(), db.guardia.findMany(), db.turno.findMany(), db.ronda.findMany(), db.entrada.findMany(), db.reporte.findMany(), db.alerta.findMany(), db.relevo.findMany(), db.configuracion.findUnique({ where: { id: 1 } })]); const configuracion = config ? Object.fromEntries(configurationFields.map(key => [key, config[key]])) : null; res.setHeader('Content-Disposition', `attachment; filename="seguridad-rrhh-${new Date().toISOString().slice(0, 10)}.json"`); res.json({ format: 'seguridad-rrhh-backup', version: 1, exported_at: new Date().toISOString(), data: { recintos, guardias, turnos, rondas, entradas, reportes, alertas, relevos, configuracion } }); }));
databaseAdmin.post('/clear', auth, admin, asyncHandler(async (req, res) => { const { password } = z.object({ password: z.string().min(1) }).parse(req.body); const user = await db.user.findUnique({ where: { id: req.user.id } }); if (!user?.password || !await bcrypt.compare(password, user.password))
    return res.status(401).json({ message: 'Contraseña incorrecta' }); await db.$transaction(clearOperationalData); res.json({ message: 'Base de datos operativa limpiada. Los usuarios y la configuración se conservaron.' }); }));
databaseAdmin.post('/import', auth, admin, asyncHandler(async (req, res) => { const backup = backupSchema.parse(req.body); const userIds = new Set((await db.user.findMany({ select: { id: true } })).map(user => user.id)); await db.$transaction(async (tx) => { await clearOperationalData(tx); const d = backup.data; if (d.recintos.length)
    await tx.recinto.createMany({ data: rowsForImport('recintos', d.recintos, userIds) }); if (d.guardias.length)
    await tx.guardia.createMany({ data: rowsForImport('guardias', d.guardias, userIds) }); if (d.turnos.length)
    await tx.turno.createMany({ data: rowsForImport('turnos', d.turnos, userIds) }); if (d.rondas.length)
    await tx.ronda.createMany({ data: rowsForImport('rondas', d.rondas, userIds) }); if (d.entradas.length)
    await tx.entrada.createMany({ data: rowsForImport('entradas', d.entradas, userIds) }); if (d.reportes.length)
    await tx.reporte.createMany({ data: rowsForImport('reportes', d.reportes, userIds) }); if (d.alertas.length)
    await tx.alerta.createMany({ data: rowsForImport('alertas', d.alertas, userIds) }); if (d.relevos.length)
    await tx.relevo.createMany({ data: rowsForImport('relevos', d.relevos, userIds) }); if (d.configuracion) {
    const config = Object.fromEntries(Object.entries(d.configuracion).filter(([key]) => configurationFields.includes(key)));
    await tx.configuracion.upsert({ where: { id: 1 }, update: config, create: { id: 1, ...config } });
} }); res.json({ message: 'Base de datos importada correctamente. Los usuarios existentes se conservaron.' }); }));
databaseAdmin.get('/rrhh/export', auth, admin, asyncHandler(async (_req, res) => { const [trabajadores, eventos, amonestaciones] = await Promise.all([db.trabajador.findMany(), db.eventoRRHH.findMany(), db.amonestacion.findMany()]); res.setHeader('Content-Disposition', `attachment; filename="seguridad-rrhh-rrhh-${new Date().toISOString().slice(0, 10)}.json"`); res.json({ format: 'seguridad-rrhh-backup', version: 1, exported_at: new Date().toISOString(), data: { trabajadores, eventos, amonestaciones } }); }));
databaseAdmin.post('/rrhh/import', auth, admin, asyncHandler(async (req, res) => { const backup = rrhhBackupSchema.parse(req.body); const userIds = new Set((await db.user.findMany({ select: { id: true } })).map(user => user.id)); await db.$transaction(async (tx) => { await clearRrhhData(tx); const d = backup.data; if (d.trabajadores.length)
    await tx.trabajador.createMany({ data: rowsForImport('trabajadores', d.trabajadores, userIds) }); if (d.eventos.length)
    await tx.eventoRRHH.createMany({ data: rowsForImport('eventos', d.eventos, userIds) }); if (d.amonestaciones.length)
    await tx.amonestacion.createMany({ data: rowsForImport('amonestaciones', d.amonestaciones, userIds) }); }); res.json({ message: 'Recursos Humanos importado correctamente. Los usuarios y datos operativos se conservaron.' }); }));
databaseAdmin.post('/rrhh/clear', auth, admin, asyncHandler(async (req, res) => { const { password } = z.object({ password: z.string().min(1) }).parse(req.body); if (!await verifyPassword(req.user.id, password))
    return res.status(401).json({ message: 'Contraseña incorrecta' }); await db.$transaction(clearRrhhData); res.json({ message: 'Recursos Humanos limpiado. Los usuarios y datos operativos se conservaron.' }); }));
databaseAdmin.get('/recintos/export', auth, admin, asyncHandler(async (_req, res) => { const recintos = await db.recinto.findMany(); res.setHeader('Content-Disposition', `attachment; filename="seguridad-rrhh-recintos-${new Date().toISOString().slice(0, 10)}.json"`); res.json({ format: 'seguridad-rrhh-recintos-backup', version: 1, exported_at: new Date().toISOString(), data: { recintos } }); }));
databaseAdmin.post('/recintos/import', auth, admin, asyncHandler(async (req, res) => { const backup = recintosBackupSchema.parse(req.body); const recintoRows = Array.isArray(backup) ? backup : backup.data.recintos; const userIds = new Set((await db.user.findMany({ select: { id: true } })).map(user => user.id)); const relatedModels = ['guardia', 'turno', 'ronda', 'entrada', 'reporte', 'alerta']; await db.$transaction(async (tx) => { const references = {}; for (const model of relatedModels)
    references[model] = await tx[model].findMany({ where: { recinto_id: { not: null } }, select: { id: true, recinto_id: true } }); await tx.recinto.deleteMany(); const rows = rowsForImport('recintos', recintoRows, userIds); if (rows.length)
    await tx.recinto.createMany({ data: rows }); const importedIds = new Set(rows.map(row => String(row.id))); for (const model of relatedModels)
    for (const item of references[model])
        if (item.recinto_id && importedIds.has(item.recinto_id))
            await tx[model].update({ where: { id: item.id }, data: { recinto_id: item.recinto_id } }); }); res.json({ message: 'Recintos importados correctamente. Las asignaciones coincidentes se conservaron.' }); }));
databaseAdmin.post('/recintos/clear', auth, admin, asyncHandler(async (req, res) => { const { password } = z.object({ password: z.string().min(1) }).parse(req.body); if (!await verifyPassword(req.user.id, password))
    return res.status(401).json({ message: 'Contraseña incorrecta' }); await db.recinto.deleteMany(); res.json({ message: 'Recintos limpiados. Los registros operativos se conservaron sin recinto asignado.' }); }));
databaseAdmin.get('/:scope/export', auth, admin, asyncHandler(async (req, res) => { const scope = moduleScopes[req.params.scope]; if (!scope)
    return res.status(404).json({ message: 'Módulo no disponible para respaldo' }); const rows = await db[scope.model].findMany(); res.setHeader('Content-Disposition', `attachment; filename="seguridad-rrhh-${req.params.scope}-${new Date().toISOString().slice(0, 10)}.json"`); res.json({ format: `seguridad-rrhh-${req.params.scope}-backup`, version: 1, exported_at: new Date().toISOString(), data: { [scope.rows]: rows } }); }));
databaseAdmin.post('/:scope/import', auth, admin, asyncHandler(async (req, res) => { const scope = moduleScopes[req.params.scope]; if (!scope)
    return res.status(404).json({ message: 'Módulo no disponible para importar' }); const backup = moduleBackupSchema.parse(req.body), rows = backup.data[scope.rows] || []; const userIds = new Set((await db.user.findMany({ select: { id: true } })).map(user => user.id)); await db.$transaction(async (tx) => { await tx[scope.model].deleteMany(); if (rows.length)
    await tx[scope.model].createMany({ data: rowsForImport(scope.rows, rows, userIds) }); }); res.json({ message: `${scope.label} importado correctamente.` }); }));
databaseAdmin.post('/:scope/clear', auth, admin, asyncHandler(async (req, res) => { const scope = moduleScopes[req.params.scope]; if (!scope)
    return res.status(404).json({ message: 'Módulo no disponible para limpiar' }); const { password } = z.object({ password: z.string().min(1) }).parse(req.body); if (!await verifyPassword(req.user.id, password))
    return res.status(401).json({ message: 'Contraseña incorrecta' }); await db[scope.model].deleteMany(); res.json({ message: `${scope.label} limpiado correctamente.` }); }));
